<?php require 'config.php';if(empty($_SESSION['cart'])){header('Location: cart.php');exit;}$pageTitle='Đặt hàng';$error='';$items=[];$total=0;$ids=array_map('intval',array_keys($_SESSION['cart']));$in=implode(',',array_fill(0,count($ids),'?'));$st=$pdo->prepare("SELECT * FROM products WHERE product_id IN ($in)");$st->execute($ids);foreach($st->fetchAll() as $p){$qty=(int)$_SESSION['cart'][$p['product_id']];if($qty>$p['quantity'])$error='Một sản phẩm không đủ tồn kho. Hãy quay lại giỏ hàng để kiểm tra.';$p['cart_qty']=$qty;$total+=$qty*$p['price'];$items[]=$p;}if($_SERVER['REQUEST_METHOD']==='POST'&&!$error){$name=trim($_POST['full_name']??'');$phone=trim($_POST['phone']??'');$address=trim($_POST['address']??'');$payment=$_POST['payment_method']??'COD';if($name===''||$phone===''||$address==='')$error='Vui lòng nhập đầy đủ họ tên, số điện thoại và địa chỉ.';else{try{$pdo->beginTransaction();$userId=$_SESSION['user']['user_id']??null;$st=$pdo->prepare('INSERT INTO orders(user_id,customer_name,phone,order_date,total_amount,status,payment_method,shipping_address) VALUES(?,?,?,NOW(),?,?,?,?)');$st->execute([$userId,$name,$phone,$total,'Chờ xác nhận',$payment,$address]);$orderId=$pdo->lastInsertId();$detail=$pdo->prepare('INSERT INTO order_details(order_id,product_id,quantity,unit_price) VALUES(?,?,?,?)');$stock=$pdo->prepare('UPDATE products SET quantity=quantity-? WHERE product_id=? AND quantity>=?');foreach($items as $p){$detail->execute([$orderId,$p['product_id'],$p['cart_qty'],$p['price']]);$stock->execute([$p['cart_qty'],$p['product_id'],$p['cart_qty']]);if($stock->rowCount()!==1)throw new Exception('Tồn kho vừa thay đổi. Vui lòng thử lại.');}$pdo->commit();unset($_SESSION['cart']);header('Location: order_success.php?id='.$orderId);exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Không thể tạo đơn hàng. Vui lòng kiểm tra tồn kho và thử lại.';}}}require 'includes/header.php';?><h1 class="section-title">Thông tin đặt hàng</h1><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><div class="row g-4"><div class="col-lg-7"><form method="post" class="content-card"><div class="mb-3"><label class="form-label">Họ và tên người nhận</label><input class="form-control" name="full_name" required value="<?= e($_SESSION['user']['full_name']??'') ?>"></div><div class="mb-3"><label class="form-label">Số điện thoại</label><input class="form-control" name="phone" required></div><div class="mb-3"><label class="form-label">Địa chỉ giao hàng</label><textarea class="form-control" name="address" rows="3" required></textarea></div><div class="mb-3"><label class="form-label">Phương thức thanh toán</label><select class="form-select" name="payment_method"><option value="COD">Thanh toán khi nhận hàng (COD)</option><option value="Bank transfer">Chuyển khoản (mô phỏng)</option></select></div><button class="btn btn-red">Xác nhận đặt hàng</button></form></div><div class="col-lg-5"><div class="content-card"><h5>Đơn hàng của bạn</h5><?php foreach($items as $p): ?><div class="d-flex justify-content-between py-2 border-bottom"><span><?= e($p['product_name']) ?> × <?= $p['cart_qty'] ?></span><strong><?= money($p['price']*$p['cart_qty']) ?></strong></div><?php endforeach; ?><div class="d-flex justify-content-between mt-3 fs-5"><strong>Tổng cộng</strong><strong class="price"><?= money($total) ?></strong></div></div></div></div><?php require 'includes/footer.php';?>
